export function drawBanana(c, x, y, s) { c.save(); c.translate(x, y); for (let k = 0; k < 3; k++) { c.save(); c.rotate(k * 2.1); c.beginPath(); c.moveTo(0, 0); c.quadraticCurveTo(s * 0.25, -s * 0.05, s * 0.38, s * 0.12); c.quadraticCurveTo(s * 0.2, s * 0.08, 0, s * 0.08); F(c, '#ffe040', s * 0.04); c.restore(); } E(c, 0, 0, s * 0.08, s * 0.08); F(c, '#8a6a2a'); c.restore(); }
export function drawDonut(c, x, y, s, t = 0) { c.save(); c.translate(x, y); E(c, 0, 0, s * 0.36, s * 0.3); F(c, '#d89a5a', s * 0.04); E(c, 0, -s * 0.02, s * 0.3, s * 0.24); F(c, '#ff8ac8'); const cols = ['#fff', '#5ad0ff', '#ffe040', '#5aff8a']; for (let k = 0; k < 10; k++) { const a = k * 0.63; c.save(); c.translate(Math.cos(a) * s * 0.2, Math.sin(a) * s * 0.15); c.rotate(a * 3); c.fillStyle = cols[k % 4]; c.fillRect(-s * 0.03, -s * 0.01, s * 0.06, s * 0.02); c.restore(); } E(c, 0, 0, s * 0.09, s * 0.07); F(c, '#5a3a1a'); c.restore(); }
export function drawShards(c, x, y, s) { c.save(); c.translate(x, y); c.globalAlpha *= 0.6; for (let k = 0; k < 6; k++) { const a = k * 1.1, r = s * (0.15 + (k % 3) * 0.1); c.save(); c.translate(Math.cos(a) * r, Math.sin(a) * r * 0.6); c.rotate(a); c.beginPath(); c.moveTo(0, -s * 0.06); c.lineTo(s * 0.08, s * 0.04); c.lineTo(-s * 0.05, s * 0.05); F(c, '#c06a3a'); c.restore(); } c.restore(); }
