export function drawSmokeBomb(c, x, y, s, rot = 0) { c.save(); c.translate(x, y); E(c, 0, 0, s * 0.26, s * 0.26); F(c, rg(c, 0, 0, s * 0.26, '#3a3a44'), s * 0.04); c.strokeStyle = '#a07040'; c.lineWidth = s * 0.05; c.beginPath(); c.moveTo(0, -s * 0.26); c.quadraticCurveTo(s * 0.1, -s * 0.4, s * 0.05, -s * 0.46); c.stroke(); E(c, s * 0.05, -s * 0.48, s * 0.05 + Math.random() * s * 0.03, s * 0.05); c.fillStyle = '#ffb030'; c.fill(); c.restore(); }
