export function drawDizzy(c, x, y, s, t) { for (let i = 0; i < 3; i++) { const a = t * 6 + i * 2.1; c.save(); c.translate(x + Math.cos(a) * s * 0.6, y + Math.sin(a) * s * 0.22); c.fillStyle = '#ffe060'; c.beginPath(); for (let k = 0; k < 10; k++) { const an = -Math.PI / 2 + k * Math.PI / 5, r = k % 2 ? s * 0.06 : s * 0.15; c.lineTo(Math.cos(an) * r, Math.sin(an) * r); } c.fill(); c.restore(); } }
export function drawEyesPeek(c, x, y, s, t) { const lk = Math.sin(t * 1.5) * s * 0.06; for (const sd of [-1, 1]) { E(c, x + sd * s * 0.14, y, s * 0.11, s * 0.13 * (((t % 3) < 0.12) ? 0.1 : 1)); F(c, '#fff', s * 0.03); E(c, x + sd * s * 0.14 + lk, y + s * 0.02, s * 0.06, s * 0.07); c.fillStyle = '#111'; c.fill(); } }
